CREATE TABLE "ciudades" (
  "id_ciudad" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "nombre_ciudad" varchar(150) NOT NULL,
  "departamento" varchar(100) NOT NULL,
  "codigo_dane_ciudad" varchar(10),
  "codigo_dane_depto" varchar(2)
);

CREATE TABLE "clientes" (
  "id_cliente" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "tipo_cliente" varchar(10) NOT NULL,
  "tipo_persona" varchar(10) NOT NULL,
  "nit" varchar(20) UNIQUE,
  "dv" VARCHAR(1),
  "razon_social" varchar(200),
  "nombre_comercial" varchar(200),
  "representante_legal" varchar(150),
  "nombre" varchar(100),
  "apellido" varchar(100),
  "email_principal" varchar(150) UNIQUE NOT NULL,
  "telefono" varchar(20),
  "id_ciudad" integer,
  "direccion" text,
  "fecha_registro" timestamp DEFAULT (CURRENT_TIMESTAMP),
  "estado" varchar(20) DEFAULT 'ACTIVO'
);

CREATE TABLE "clientes_pospago" (
  "id_cliente" integer PRIMARY KEY,
  "limite_credito" decimal(15,2) DEFAULT 0,
  "credito_disponible" decimal(15,2) DEFAULT 0,
  "estado_mora" varchar(20) DEFAULT 'NORMAL',
  "dias_mora" integer DEFAULT 0,
  "fecha_ultima_factura" date,
  "ultima_revision_credito" date,
  "requiere_aprobacion" boolean DEFAULT true
);

CREATE TABLE "soportes_clientes" (
  "id_soporte" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_cliente" integer NOT NULL,
  "tipo_soporte" varchar(100) NOT NULL,
  "fecha_solicitud" date DEFAULT (CURRENT_DATE),
  "fecha_vencimiento" date,
  "estado" varchar(50) DEFAULT 'pendiente',
  "archivo_adjunto" varchar(255),
  "fecha_entrega" date,
  "observaciones" text,
  "usuario_registra" varchar(50) NOT NULL,
  "validado_por" varchar(50),
  "fecha_validacion" timestamp
);

CREATE TABLE "candidatos" (
  "id_candidato" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "cedula" varchar(20) UNIQUE NOT NULL,
  "tipo_documento" varchar(20) NOT NULL,
  "nombres" varchar(200) NOT NULL,
  "apellidos" varchar(200) NOT NULL,
