  "equipo" varchar(100),
  "conclusion_tecnica" text
);

CREATE TABLE "preguntas_relevantes_poligrafia" (
  "id_pregunta_relevante" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_informe_poligrafia" integer NOT NULL,
  "pregunta" text,
  "respuesta" varchar(10),
  "calificacion" integer
);

CREATE TABLE "autorizacion_poligrafia" (
  "id_autorizacion" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_informe_poligrafia" integer NOT NULL,
  "soporte" varchar(100),
  "documento_cargado" varchar(255)
);

CREATE TABLE "documentos" (
  "id_documento" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_servicio" integer NOT NULL,
  "tipo_documento" varchar(100) NOT NULL,
  "nombre_archivo" varchar(255) NOT NULL,
  "ruta_archivo" varchar(255),
  "tamano_archivo" bigint,
  "fecha_carga" timestamp DEFAULT (CURRENT_TIMESTAMP),
  "fecha_solicitud" date,
  "fecha_recibido" date,
  "descripcion" text,
  "comunicados" text,
  "estado_documento" varchar(50) DEFAULT 'PENDIENTE'
);

CREATE TABLE "informes_analisis_final" (
  "id_informe_final" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_servicio" integer NOT NULL,
  "id_candidato" bigint NOT NULL,
  "id_analista" integer NOT NULL,
  "fecha_informe" date DEFAULT (CURRENT_DATE),
  "concepto_poligrafia" text,
  "concepto_visita" text,
  "concepto_antecedentes_legales" text,
  "concepto_antecedentes_financieros" text,
  "concepto_academico" text,
  "concepto_laboral" text,
  "concepto_referencias_personales" text,
  "concepto_final_general" varchar(50) NOT NULL,
  "recomendacion" varchar(100),
  "observaciones_finales" text,
  "fecha_revision" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

